// Noto Sans (SIL Open Font License 1.1, https://openfontlicense.org), subset to Latin, Latin Extended,
// Vietnamese, Greek, Cyrillic, general punctuation and currency symbols. Regenerate with fontTools.subset.
// CJK, Arabic, Hebrew, Thai and Indic scripts are not included; those characters print as "?".
// Base64 so every runtime (Node, Bun, browsers, compiled binaries) loads it without file access.
export const NOTO_SANS_REGULAR_B64 =
  '';
export const NOTO_SANS_BOLD_B64 =
  '';

export function b64ToBytes(b64: string): Uint8Array {
  if (typeof atob === 'function') {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  return new Uint8Array(Buffer.from(b64, 'base64'));
}
